    id: string;                     // "goal-001"
    title: string;
    description: string;
    priority: "P0" | "P1" | "P2" | "P3";
    confirmed: boolean;             // user-confirmed vs inferred
  }[];

  nonFunctionalRequirements: {
    id: string;                     // "nfr-001"
    category: string;               // e.g., "Performance", "Security"
    description: string;
    confirmed: boolean;
  }[];

  userStories: {
    id: string;                     // "us-001"
    asA: string;
    iWant: string;
    soThat: string;
    acceptanceCriteria: string[];
    confirmed: boolean;
  }[];

  constraints: {
    id: string;                     // "con-001"
