    responsibilities: string;
  }[];

  lifecycle: {
    id: string;                     // "lc-001"
    phase: string;                  // e.g., "MVP", "v1.0"
    description: string;
  }[];

  assumptionsConfirmed: boolean;    // global flag: has user reviewed & confirmed assumptions?

  changelog: {
    id: string;                     // "cl-001"
