If you want something that will comfortably pass `n ~ 2e5, k ~ 200+`:

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (ll)4e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<ll> x(n + 1), w(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> x[i] >> w[i];
    }

    vector<ll> W(n + 1), SX(n + 1);
    for (int i = 1; i <= n; ++i) {
        W[i] = W[i - 1] + w[i];
        SX[i] = SX[i - 1] + w[i] * x[i];
    }

    int K = min(k, n);
    vector<ll> dp_prev(n + 1, INF), dp_cur(n + 1, INF);
    dp_prev[0] = 0;

    auto segment_cost = [&](int L, int R) -> ll {
        // find weighted median index m in [L, R]
        ll totalW = W[R] - W[L - 1];
        ll halfW = (totalW + 1) / 2;
        int lo = L, hi = R;
        ll base = W[L - 1];
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (W[mid] - base >= halfW) hi = mid;
            else lo = mid + 1;
        }
        int m = lo;
        ll xm = x[m];

        // left
        ll sW_left = W[m] - W[L - 1];
        ll sSX_left = SX[m] - SX[L - 1];
        ll left_cost = xm * sW_left - sSX_left;

        // right
        ll sW_right = W[R] - W[m];
        ll sSX_right = SX[R] - SX[m];
        ll right_cost = sSX_right - xm * sW_right;

        return left_cost + right_cost;
    };

    function<void(int,int,int,int)> compute_row = [&](int l, int r, int optL, int optR) {
        if (l > r) return;
        int mid = (l + r) / 2;
        ll bestVal = INF;
        int bestJ = -1;

        int endJ = min(optR, mid - 1);
        for (int j = optL; j <= endJ; ++j) {
            ll val = dp_prev[j] + segment_cost(j + 1, mid);
            if (val < bestVal) {
                bestVal = val;
                bestJ = j;
            }
        }
        dp_cur[mid] = bestVal;

        if (l < mid) compute_row(l, mid - 1, optL, bestJ);
        if (mid < r) compute_row(mid + 1, r, bestJ, optR);
    };

    for (int t = 1; t <= K; ++t) {
        fill(dp_cur.begin(), dp_cur.end(), INF);
        dp_cur[0] = 0;
        compute_row(1, n, 0, n - 1);
        dp_prev.swap(dp_cur);
    }

    cout << dp_prev[n] << '\n';
    return 0;
}
```

