## 1. Simple `O(n² + k n)` DP (precompute all costs)

Use this if `n <= ~3000–5000` and `k <= n` in C++ with ~1s.

### Precompute prefix sums and segment costs

```cpp
const long long INF = (1LL << 62);

int n, k;
vector<long long> x(n+1), w(n+1);
vector<long long> W(n+1), WX(n+1);  // prefix sums

// read n, k, x[i], w[i] ...
// if x[i] not sorted, sort by x and carry w along

for (int i = 1; i <= n; ++i) {
    W[i]  = W[i-1]  + w[i];
    WX[i] = WX[i-1] + w[i] * x[i];
}

// cost[L][R] for all 1 <= L <= R <= n
vector<vector<long long>> cost(n+1, vector<long long>(n+1, 0));

for (int L = 1; L <= n; ++L) {
    int m = L;
    // Move m as weighted median as R increases
    for (int R = L; R <= n; ++R) {
        // Maintain weighted median index m in [L..R]
        // In 1D with weights: median m s.t. W[m] - W[L-1] >= (W[R] - W[L-1] + 1)/2
        while (m+1 <= R) {
            long long leftWeight  = W[m]   - W[L-1];
            long long rightWeight = W[R]   - W[m];
            long long nextLeft    = W[m+1] - W[L-1];
            long long nextRight   = W[R]   - W[m+1];
            // Move m to m+1 only if it's still a valid or better median
            if (nextLeft <= nextRight) m++;
            else break;
        }
        int M = m; // median index

        // Cost to move [L..R] to x[M]:
        // left part: sum_{i=L..M} w[i]*(x[M]-x[i])
        // right part: sum_{i=M+1..R} w[i]*(x[i]-x[M])
        auto sumW  = [&](int l, int r) { return W[r] - W[l-1]; };
        auto sumWX = [&](int l, int r) { return WX[r] - WX[l-1]; };

        long long leftW   = sumW(L, M);
        long long leftWX  = sumWX(L, M);
        long long rightW  = (M+1 <= R) ? sumW(M+1, R) : 0;
        long long rightWX = (M+1 <= R) ? sumWX(M+1, R) : 0;

        long long cLeft  = x[M]*leftW  - leftWX;
        long long cRight = rightWX - x[M]*rightW;

        cost[L][R] = cLeft + cRight;
    }
}
```

This is amortized `O(n²)` because `m` moves at most `n` steps for each fixed `L` over all `R`.

### DP: `dp[g][i] = min cost to cover first i points with g groups`

```cpp
vector<vector<long long>> dp(k+1, vector<long long>(n+1, INF));
dp[0][0] = 0;

for (int g = 1; g <= k; ++g) {
    for (int i = 1; i <= n; ++i) {
        long long best = INF;
        // last group covers [j+1..i]
        for (int j = 0; j < i; ++j) {
            best = min(best, dp[g-1][j] + cost[j+1][i]);
        }
        dp[g][i] = best;
    }
}

long long answer = dp[k][n];
```

This is `O(k n²)` for that innermost `j` loop, which is only acceptable if `n` is quite small (`<= 1000–1500`) or `k` very small.  

More typical is to **keep only the O(n²) precompute and make the DP `O(k n)` with a trick** (see below), but in practice you’ll likely want the D&C optimization for larger `n`.

